    REG_WIDTH = 16  # 本基准目标器件寄存器宽度（16 位为主）

    def __init__(self):
        self.regs = {0x00: 0x0000, 0x01: 0x0000, 0x02: 0x0000, 0x03: 0x0000}  # addr(int) -> value(int)

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if nbytes == 2:
            return self.regs[addr]
        else:
            return (self.regs[addr] & 0xFF00) >> 8

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if nbytes == 2:
            self.regs[addr] = data
        else:
            self.regs[addr] = (self.regs[addr] & 0x00FF) | ((data & 0x00FF) << 8)

        if addr == 0x00 and self.regs[addr] & 0x0008:  # PGA_BYPASS bit is RW
            self.regs[addr] |= 0x0008

