class ADS1220_Simulator(BaseVirtualSensor):
    def __init__(self):
        super().__init__()
        self.regs = {0x00: 0x00, 0x01: 0x00, 0x02: 0x00, 0x03: 0x00}

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: 0x{addr:02x}")
        if nbytes not in (1, 2):
            raise ValueError(f"Invalid number of bytes: {nbytes}")

        data = self.regs[addr]

        if nbytes == 1:
            data = (data & 0xFF00) | ((data >> 8) & 0xFF)

        return data

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: 0x{addr:02x}")
        if nbytes not in (1, 2):
            raise ValueError(f"Invalid number of bytes: {nbytes}")

        if nbytes == 2:
            self.regs[addr] = data
        else:
            self.regs[addr] = (self.regs[addr] & 0xFF00) | (data & 0xFF)

        # Handle read-only and write-only fields
        if addr == 0x00:
            if (data & 0xF0) != (self.regs[addr] & 0xF0):
                self.regs[addr] = (self.regs[addr] & 0x00FF) | ((data & 0xF0) << 8)
        elif addr == 0x03:
            if (data & 0x80) != (self.regs[addr] & 0x80):
                self.regs[addr] = (self.regs[addr] & 0x7F00) | (data & 0x7F)

